syntax = "proto3";
package spacefractions;
service GameService {
  rpc Play(PlayRequest) returns (PlayResponse) {}
}
message PlayRequest {
  int32 gameId = 1;
}
message PlayResponse {
  int32 gameId = 1;
}

CREATE TABLE games (
  id SERIAL PRIMARY KEY,
  game_state JSONB NOT NULL
);

